{
  "copy": "<div class="row sectionBlockLayout text-start" style="display: flex; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="display: flex; flex-wrap: wrap;">
    <div class="col-lg-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px; padding: 16px; margin: 60px 0px;">
      <h2>Test: Create Offering Acceptance</h2>
      <p>This page attempts to create a single Offering Acceptance record with hard‑coded values.</p>
      <button id="testCreateBtn" style="padding: 10px 16px; font-size: 16px;">Create Offering Acceptance</button>
      <pre id="output" style="margin-top: 16px; padding: 12px; background: #f6f8fa; border: 1px solid #ddd; white-space: pre-wrap;"></pre>
      <script>
        (async function(){

          const output = document.getElementById("output");
          const btn = document.getElementById("testCreateBtn");

          function log(msg){
            output.textContent += msg + "\n";
          }

          async function getCsrfToken(){
            const res = await fetch("/_layout/tokenhtml", { credentials: "same-origin" });
            const text = await res.text();
            const doc = new DOMParser().parseFromString(text, "text/html");
            const input = doc.querySelector("input[name='__RequestVerificationToken']");
            if (!input) throw new Error("CSRF token not found");
            return input.value;
          }

          btn.addEventListener("click", async function(){

            output.textContent = "";
            log("Starting create test...");

            const payload = {
              "hit_baseamount": 123,
              "hit_Offering@odata.bind": "/hit_offerings(ed2ec11a-5b09-f111-8407-000d3a7a0035)"
            };

            log("Payload:");
            log(JSON.stringify(payload, null, 2));

            try {
              const token = await getCsrfToken();
              log("CSRF token acquired");

              const res = await fetch("/_api/hit_offeringacceptances", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                  "Accept": "application/json",
                  "__RequestVerificationToken": token,
                  "OData-Version": "4.0",
                  "OData-MaxVersion": "4.0"
                },
                body: JSON.stringify(payload)
              });

              log("HTTP status: " + res.status);

              const body = await res.text();
              log("Raw response:");
              log(body || "(empty)");

            } catch (err){
              log("Error:");
              log(err.message || String(err));
            }

          });

        })();
      </script>
    </div>
  </div>
</div>
